@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&display=swap');

/* HEE evidence map — app styles
   Ink-and-paper editorial look: deep navy chrome, warm paper background,
   serif display headings (Newsreader) over Inter body text. */

:root {
  --hee-ink: #10243e;
  --hee-ink-soft: #33475f;
  --hee-paper: #faf9f6;
  --hee-line: #e7e3da;
  --hee-muted: #6b7280;
  --hee-accent: #1f5fa8;
  --hee-gold: #b08d3e;
}

/* ---- chrome ---- */
.navbar {
  background: linear-gradient(95deg, #0d1f36 0%, #16324f 100%) !important;
  box-shadow: 0 1px 10px rgba(13, 31, 54, .28);
  padding-top: .35rem;
  padding-bottom: .35rem;
}
.navbar .navbar-brand {
  font-family: 'Newsreader', Georgia, serif;
  font-weight: 600;
  letter-spacing: .02em;
  color: #f4f1ea !important;
}
.navbar .nav-link {
  color: rgba(232, 236, 243, .82) !important;
  font-weight: 500;
  font-size: .92rem;
  letter-spacing: .015em;
  border-radius: 8px;
  padding: .42rem .8rem !important;
  transition: background .15s ease, color .15s ease;
}
.navbar .nav-link:hover { color: #fff !important; background: rgba(255, 255, 255, .08); }
.navbar .nav-link.active,
.navbar .nav-item.show .nav-link {
  color: #fff !important;
  background: rgba(176, 141, 62, .28);
  box-shadow: inset 0 -2px 0 var(--hee-gold);
}
.navbar .dropdown-menu {
  border: 1px solid var(--hee-line);
  border-radius: 12px;
  box-shadow: 0 14px 34px rgba(13, 31, 54, .18);
  padding: .4rem;
}
.navbar .dropdown-item {
  border-radius: 8px;
  font-size: .9rem;
  padding: .45rem .7rem;
}
.navbar .dropdown-item:hover { background: #f1eee7; }
.navbar-text { color: rgba(232, 236, 243, .55) !important; }

body { background: var(--hee-paper); font-family: 'Inter', system-ui, -apple-system, sans-serif; }

h1, h2, h3, h4, h5,
.card-header, .value-box .value-box-title {
  font-family: 'Newsreader', Georgia, serif;
}

/* ---- cards ---- */
.card {
  background: #fff;
  border: 1px solid var(--hee-line);
  border-radius: 14px;
  box-shadow: 0 1px 3px rgba(16, 36, 62, .05);
}
.card-header {
  background: transparent;
  border-bottom: 1px solid var(--hee-line);
  font-weight: 600;
  font-size: 1.02rem;
  letter-spacing: .01em;
  color: var(--hee-ink);
  padding: .8rem 1.1rem;
}

/* ---- overview ---- */
.hero-title {
  font-size: 1.75rem;
  font-weight: 600;
  color: var(--hee-ink);
  margin-bottom: .6rem;
  line-height: 1.25;
}
.hero-text {
  max-width: 85ch;
  color: var(--hee-ink-soft);
  font-size: .98rem;
  line-height: 1.65;
}
.hero-img {
  width: 100%;
  display: block;
  cursor: zoom-in;
  border-radius: 13px;
  transition: transform .18s ease, box-shadow .18s ease;
}
.hero-img:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(16, 36, 62, .14);
}

/* ---- value boxes ---- */
.value-box {
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, .12);
  box-shadow: 0 1px 3px rgba(16, 36, 62, .08);
}
.value-box .value-box-title {
  font-size: .82rem;
  text-transform: uppercase;
  letter-spacing: .07em;
  opacity: .85;
}
.value-box .value-box-value { font-size: 1.55rem; font-weight: 600; }
.value-box.bg-secondary { background: linear-gradient(120deg, #46586e, #33475f) !important; }
.value-box.bg-primary   { background: linear-gradient(120deg, #2468b2, #1a4e8a) !important; }
.value-box.bg-info      { background: linear-gradient(120deg, #2a8fc4, #1f6f9c) !important; }
.value-box.bg-success   { background: linear-gradient(120deg, #1baf7a, #148c62) !important; }

/* ---- gallery ---- */
.theme-wrap { max-width: 1400px; margin: 0 auto; padding: .5rem .25rem 2rem; }
.theme-blurb {
  max-width: 78ch;
  color: var(--hee-ink-soft);
  font-size: .95rem;
  line-height: 1.65;
  margin: .25rem 0 1.5rem;
  padding-left: .9rem;
  border-left: 3px solid var(--hee-gold);
}
.fig-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 1.4rem;
}
.fig-card {
  background: #fff;
  border: 1px solid var(--hee-line);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 1px 3px rgba(16, 36, 62, .05);
  transition: transform .18s ease, box-shadow .18s ease;
  display: flex;
  flex-direction: column;
}
.fig-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 30px rgba(16, 36, 62, .14);
}
.fig-card img {
  width: 100%;
  display: block;
  cursor: zoom-in;
  background: #fff;
  border-bottom: 1px solid var(--hee-line);
}
.fig-body { padding: .85rem 1.05rem 1rem; }
.fig-title {
  font-family: 'Newsreader', Georgia, serif;
  font-weight: 600;
  font-size: 1rem;
  color: var(--hee-ink);
}
.fig-caption {
  color: var(--hee-muted);
  font-size: .82rem;
  line-height: 1.5;
  margin-top: .3rem;
}

/* ---- figure modal ---- */
.modal-content {
  border-radius: 16px;
  border: 1px solid var(--hee-line);
}
.modal-title { font-family: 'Newsreader', Georgia, serif; font-weight: 600; color: var(--hee-ink); }
.modal-fig { width: 100%; display: block; }

/* ---- explorer ---- */
.sidebar {
  background: #f6f4ee;
  border-right: 1px solid var(--hee-line);
}
.sidebar .control-label, .sidebar legend {
  font-size: .78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--hee-ink-soft);
}
.sidebar .shiny-input-container { margin-bottom: .9rem; }
.selectize-input { border-radius: 9px; border-color: var(--hee-line); }
.form-control, .selectize-input, .form-select {
  border-radius: 9px;
  border-color: var(--hee-line);
}
.form-control:focus, .selectize-input.focus {
  border-color: var(--hee-accent);
  box-shadow: 0 0 0 .18rem rgba(31, 95, 168, .14);
}
.irs-bar { background: var(--hee-accent); border-color: var(--hee-accent); }
.irs-from, .irs-to, .irs-single { background: var(--hee-accent); }
.irs-from:after, .irs-to:after, .irs-single:after { border-top-color: var(--hee-accent); }

/* ---- tables ---- */
table.dataTable thead th {
  font-size: .78rem;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--hee-ink-soft);
  border-bottom: 2px solid var(--hee-line) !important;
}
table.dataTable tbody td { font-size: .88rem; }

/* ---- plotly ---- */
.js-plotly-plot .plotly .main-svg { font-family: 'Inter', sans-serif !important; }

/* ---- country fact list (sidebar definition list) ---- */
.fact-list { margin-bottom: 0; }
.fact-list dt {
  text-transform: uppercase;
  font-size: .72rem;
  letter-spacing: .06em;
  color: var(--hee-muted);
  margin-top: .7rem;
}
.fact-list dd {
  font-size: .95rem;
  color: var(--hee-ink);
  font-weight: 500;
  margin: 0;
}

/* ---- overview glance heading ---- */
.glance-title {
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--hee-ink);
  margin: 1.5rem 0 .8rem;
}

/* ---- methods tab ---- */
.methods-wrap { max-width: 90ch; margin: 0 auto; padding: .5rem .25rem 2rem; }
.methods-wrap .card { margin-bottom: 1.2rem; }
.methods-wrap p {
  color: var(--hee-ink-soft);
  font-size: .94rem;
  line-height: 1.6;
}
.methods-table { width: 100%; border-collapse: collapse; margin: .4rem 0 .6rem; }
.methods-table th {
  text-transform: uppercase;
  font-size: .74rem;
  letter-spacing: .05em;
  color: var(--hee-muted);
  font-weight: 600;
  text-align: left;
  padding: .45rem .6rem;
  border-bottom: 1px solid var(--hee-line);
}
.methods-table td {
  padding: .45rem .6rem;
  font-size: .92rem;
  color: var(--hee-ink-soft);
  border-bottom: 1px solid var(--hee-line);
  text-align: left;
}
.methods-table td:first-child { text-align: left; }
.methods-note { font-size: .8rem; color: var(--hee-muted); margin-top: .5rem; }
